259:   update(dt, time, otherEnemies) {
260:     this.age += dt;
261:     const target = camera.position;
262:     const group = this.group;
263:     const scale = lerp(group.scale.x, this.baseScale, 1 - Math.exp(-8 * dt));
264:     group.scale.setScalar(scale);
265: 
266:     const toX = target.x - group.position.x;
267:     const toZ = target.z - group.position.z;
268:     const flatDist = Math.max(0.001, Math.hypot(toX, toZ));
269:     const nx = toX / flatDist;
270:     const nz = toZ / flatDist;
271:     const orbit = (this.heavy ? 13 : 10) + Math.sin(this.age * 0.55 + this.seed) * 2.5;
272:     const strafe = Math.sin(this.age * 0.42 + this.seed * 1.7) * (this.heavy ? 2.2 : 3.2);
273: 
274:     let tx = group.position.x + nx * (flatDist - orbit) - nz * strafe;
275:     let tz = group.position.z + nz * (flatDist - orbit) + nx * strafe;
276:     let ty = (this.heavy ? 2.45 : 2.05) + Math.sin(this.age * 1.7 + this.seed) * 0.22;
277: 
278:     // separation
279:     for (const other of otherEnemies) {
280:       if (other === this || other.dead) continue;
281:       const dx = group.position.x - other.group.position.x;
282:       const dz = group.position.z - other.group.position.z;
283:       const d = Math.hypot(dx, dz);
284:       if (d > 0.001 && d < this.radius + other.radius + 0.9) {
285:         const push = (this.radius + other.radius + 0.9 - d) * 3.2;
286:         tx += (dx / d) * push;
287:         tz += (dz / d) * push;
288:       }
289:     }
290: 
291:     this.vel.x += (tx - group.position.x) * 1.4 * dt;
292:     this.vel.z += (tz - group.position.z) * 1.4 * dt;
293:     this.vel.y += (ty - group.position.y) * 2.2 * dt;
294:     const damp = Math.exp(-1.25 * dt);
295:     this.vel.x *= damp;
296:     this.vel.z *= damp;
297:     this.vel.y *= damp;
298:     const maxSpeed = this.speed;
299:     if (this.vel.length() > maxSpeed) this.vel.setLength(maxSpeed);
300:     group.position.addScaledVector(this.vel, dt);
301:     group.position.x = clamp(group.position.x, -29, 29);
302:     group.position.z = clamp(group.position.z, -29, 29);
303:     group.position.y = clamp(group.position.y, 1.15, 6.5);
304: 
305:     group.lookAt(target);
306:     this.ring1.rotation.z += dt * 1.7;
307:     this.ring2.rotation.x += dt * 2.3;
308:     this.eyePulse += dt * 5;
309:     const pulse = 0.86 + Math.sin(this.eyePulse) * 0.14;
310:     this.eyeMat.color.setRGB(
311:       (this.heavy ? 1 : 1) * pulse,
312:       (this.heavy ? 0.25 : 0.62) * pulse,
313:       (this.heavy ? 0.18 : 0.28) * pulse
314:     );
315:     if (this.flash > 0) {
316:       this.flash -= dt;
317:       this.bodyMat.emissiveIntensity = Math.max(0, this.flash / 0.14) * 2.4;
318:     } else {
319:       this.bodyMat.emissiveIntensity = this.baseEmissiveIntensity;
320:       this.bodyMat.emissive.copy(this.baseEmissive);
321:     }
322: 
323:     this.fireTimer -= dt;
324:     let shouldFire = false;
325:     if (this.fireTimer <= 0 && flatDist < 38 && this.age > 1.2) {
326:       shouldFire = true;
327:       this.fireTimer = Math.max(1.05, 2.9 - game.wave * 0.14) + Math.random() * 0.8;
328:     }
329:     this.eyeWorld.set(0, 0.05, 0.55);
330:     group.updateMatrixWorld(true);
331:     group.localToWorld(this.eyeWorld);
332:     return shouldFire;
333:   }
334: }
