584: function addTracer(from, to, color = 0x9fe6ff, life = 0.075) {
585:   const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
586:   const mat = new THREE.LineBasicMaterial({
587:     color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false,
588:   });
