594: function addRing(position, color = 0xff9d2e, size = 1, life = 0.55) {
595:   const geo = new THREE.RingGeometry(0.55, 0.75, 32);
596:   const mat = new THREE.MeshBasicMaterial({
597:     color, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
598:     blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
599:   });
600:   const ring = new THREE.Mesh(geo, mat);
601:   ring.scale.setScalar(size);
602:   ring.rotation.x = -Math.PI / 2;
603:   ring.position.copy(position);
604:   ring.position.y = Math.max(0.05, position.y);
605:   scene.add(ring);
606:   effects.push({ type: 'ring', obj: ring, life, max: life, growth: 3.6 });
607: }
608: 
609: function updateEffects(dt) {
610:   for (let i = effects.length - 1; i >= 0; i--) {
611:     const e = effects[i];
612:     e.life -= dt;
613:     const t = 1 - Math.max(0, e.life) / e.max;
614:     if (e.type === 'line') {
615:       e.obj.material.opacity = (1 - t) * 0.9;
616:     } else if (e.type === 'ring') {
617:       e.obj.scale.setScalar(1 + t * e.growth);
618:       e.obj.material.opacity = (1 - t) * 0.85;
619:     }
620:     if (e.life <= 0) {
621:       scene.remove(e.obj);
622:       e.obj.geometry.dispose();
623:       e.obj.material.dispose();
624:       effects.splice(i, 1);
625:     }
626:   }
627:   for (const slot of flashPool) {
628:     if (slot.life > 0) {
629:       slot.life -= dt;
630:       slot.light.intensity = Math.max(0, slot.life / slot.max) * slot.base;
631:     }
632:   }
633: }
