784: // ---------------------------------------------------------------- touch
785: if (isTouch) {
786:   document.body.classList.add('touch-device');
787:   const stick = $('stick-base');
788:   const knob = $('stick-knob');
789:   stick.addEventListener('pointerdown', (e) => {
790:     e.preventDefault();
791:     stickId = e.pointerId;
792:     const rect = stick.getBoundingClientRect();
793:     stickCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
794:     try { stick.setPointerCapture(e.pointerId); } catch { /* ignore */ }
795:     moveStick(e.clientX, e.clientY);
796:   });
797:   const moveStick = (x, y) => {
798:     let dx = x - stickCenter.x;
799:     let dy = y - stickCenter.y;
800:     const max = 38;
801:     const len = Math.hypot(dx, dy);
802:     if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
803:     knob.style.transform = `translate(${dx}px, ${dy}px)`;
804:     touchMove.x = dx / max;
805:     touchMove.y = dy / max;
806:   };
807:   stick.addEventListener('pointermove', (e) => {
808:     if (e.pointerId !== stickId) return;
809:     moveStick(e.clientX, e.clientY);
810:   });
811:   const endStick = (e) => {
812:     if (e.pointerId !== stickId) return;
813:     stickId = null;
814:     touchMove.x = 0;
815:     touchMove.y = 0;
816:     knob.style.transform = 'translate(0,0)';
817:   };
818:   stick.addEventListener('pointerup', endStick);
819:   stick.addEventListener('pointercancel', endStick);
