71: function windowTextures(seed) {
72:   const width = 128;
73:   const height = 256;
74:   const rand = mulberry32(seed);
75:   const cols = 5 + Math.floor(rand() * 2);
76:   const rows = 10 + Math.floor(rand() * 4);
77:   const color = document.createElement('canvas');
78:   color.width = width; color.height = height;
79:   const c = color.getContext('2d');
80:   const emit = document.createElement('canvas');
81:   emit.width = width; emit.height = height;
82:   const e = emit.getContext('2d');
83:   c.fillStyle = '#151a20';
84:   c.fillRect(0, 0, width, height);
85:   e.fillStyle = '#000';
86:   e.fillRect(0, 0, width, height);
87:   for (let i = 0; i < 900; i++) {
88:     const g = 16 + rand() * 20;
89:     c.fillStyle = `rgba(${g},${g + 2},${g + 4},0.35)`;
90:     c.fillRect(rand() * width, rand() * height, 1 + rand() * 2, 1 + rand() * 8);
91:   }
92:   const padX = 10;
93:   const padY = 12;
94:   const cw = (width - padX * 2) / cols;
95:   const ch = (height - padY * 2) / rows;
96:   for (let row = 0; row < rows; row++) {
97:     for (let col = 0; col < cols; col++) {
98:       const x = padX + col * cw + 3;
99:       const y = padY + row * ch + 4;
100:       const ww = cw - 6;
101:       const hh = ch - 8;
102:       const lit = rand() > 0.43;
103:       const warm = rand() > 0.42;
104:       const alpha = 0.35 + rand() * 0.65;
105:       c.fillStyle = lit
106:         ? warm ? `rgba(255, ${140 + rand() * 60}, 70, ${alpha})` : `rgba(90, 190, 235, ${alpha * 0.8})`
107:         : 'rgba(7, 10, 14, 0.92)';
108:       c.fillRect(x, y, ww, hh);
109:       c.fillStyle = 'rgba(2,3,5,0.55)';
110:       c.fillRect(x, y, ww, 1.5);
111:       if (lit) {
112:         e.fillStyle = warm ? `rgba(255, ${125 + rand() * 70}, 55, ${alpha})` : `rgba(70, 160, 220, ${alpha * 0.8})`;
113:         e.fillRect(x, y, ww, hh);
114:         if (rand() > 0.7) {
115:           e.fillStyle = 'rgba(0,0,0,0.7)';
116:           e.fillRect(x + ww * 0.4, y, ww * 0.13, hh);
117:         }
118:       }
119:     }
120:   }
121:   c.fillStyle = 'rgba(8,11,15,0.5)';
122:   for (let i = 0; i < 10; i++) {
123:     c.fillRect(0, rand() * height, width, 1 + rand() * 3);
124:   }
125:   const map = new THREE.CanvasTexture(color);
126:   map.colorSpace = THREE.SRGBColorSpace;
127:   const emissive = new THREE.CanvasTexture(emit);
128:   emissive.colorSpace = THREE.SRGBColorSpace;
129:   return { map, emissive };
130: }
