98: function cloneRepeat(texture, x, y) {
99:   const clone = texture.clone();
100:   clone.needsUpdate = true;
101:   clone.wrapS = clone.wrapT = THREE.RepeatWrapping;
102:   clone.repeat.set(x, y);
103:   return clone;
104: }
