106: function facadeMaterial(tex, repeatX, repeatY) {
107:   return new THREE.MeshStandardMaterial({
108:     map: cloneRepeat(tex.map, repeatX, repeatY),
109:     emissiveMap: cloneRepeat(tex.emissive, repeatX, repeatY),
110:     roughnessMap: cloneRepeat(tex.roughness, repeatX, repeatY),
111:     emissive: 0xffffff,
112:     emissiveIntensity: 0.38,
113:     roughness: 0.92,
114:     metalness: 0.12,
115:     envMapIntensity: 0.35,
116:   });
