119: function makeBuilding(scene, occluders, rand, angle, radius, index) {
120:   const width = 8 + rand() * 16;
121:   const depth = 8 + rand() * 12;
122:   const height = 11 + rand() * 30;
123:   const x = Math.cos(angle) * radius;
124:   const z = Math.sin(angle) * radius;
125:   const tex = windowTextures(100 + index);
126:   const roofMat = new THREE.MeshStandardMaterial({
127:     color: 0x171c22, roughness: 0.96, metalness: 0.08,
128:   });
129:   // One texture tile spans roughly 10 m, so window size stays believable on every face.
130:   const matX = facadeMaterial(tex, Math.max(0.6, depth / 10), Math.max(0.35, height / 58));
131:   const matZ = facadeMaterial(tex, Math.max(0.6, width / 10), Math.max(0.35, height / 58));
132:   const mesh = new THREE.Mesh(
133:     new THREE.BoxGeometry(width, height, depth),
134:     [matX, matX, roofMat, roofMat, matZ, matZ]
135:   );
136:   mesh.position.set(x, height / 2, z);
137:   mesh.rotation.y = -angle + (rand() - 0.5) * 0.4;
138:   mesh.castShadow = true;
139:   mesh.receiveShadow = true;
140:   scene.add(mesh);
141:   occluders.push(mesh);
142: 
143:   // roof cap, parapet and rooftop clutter
144:   const roof = new THREE.Mesh(
145:     new THREE.BoxGeometry(width + 0.6, 0.5, depth + 0.6),
146:     roofMat
147:   );
148:   roof.position.set(x, height + 0.25, z);
149:   roof.rotation.y = mesh.rotation.y;
150:   roof.castShadow = true;
151:   roof.receiveShadow = true;
152:   scene.add(roof);
153:   occluders.push(roof);
154: 
155:   const detailMat = new THREE.MeshStandardMaterial({
156:     color: 0x222a32, roughness: 0.68, metalness: 0.45, envMapIntensity: 0.5,
157:   });
158:   const local = (dx, dz, y) => {
159:     const cos = Math.cos(mesh.rotation.y);
160:     const sin = Math.sin(mesh.rotation.y);
161:     return new THREE.Vector3(x + dx * cos - dz * sin, y, z + dx * sin + dz * cos);
162:   };
163:   for (let i = 0; i < 3; i++) {
164:     const w = 1 + rand() * 2.4;
165:     const d = 1 + rand() * 2.2;
166:     const h = 0.5 + rand() * 1.2;
167:     const box = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), detailMat);
168:     const pos = local((rand() - 0.5) * width * 0.62, (rand() - 0.5) * depth * 0.62, height + 0.5 + h / 2);
169:     box.position.copy(pos);
170:     box.rotation.y = mesh.rotation.y;
171:     box.castShadow = true;
172:     box.receiveShadow = true;
173:     scene.add(box);
174:   }
175: 
176:   if (rand() > 0.45) {
177:     const mast = new THREE.Mesh(
178:       new THREE.CylinderGeometry(0.09, 0.14, 5 + rand() * 7, 5),
179:       detailMat
180:     );
181:     mast.position.set(x + (rand() - 0.5) * width * 0.3, height + 3, z + (rand() - 0.5) * depth * 0.3);
182:     mast.castShadow = true;
183:     scene.add(mast);
184:     const beacon = new THREE.Mesh(
185:       new THREE.SphereGeometry(0.16, 8, 6),
186:       new THREE.MeshBasicMaterial({ color: 0xff4530, toneMapped: false })
187:     );
188:     beacon.position.copy(mast.position).add(new THREE.Vector3(0, 3.6, 0));
189:     scene.add(beacon);
190:   }
191: }
