105:       const index = (y * size + x) * 4;
106:       image.data[index] = (nx * 0.5 + 0.5) * 255;
107:       image.data[index + 1] = (ny * 0.5 + 0.5) * 255;
108:       image.data[index + 2] = (nz * 0.5 + 0.5) * 255;
109:       image.data[index + 3] = 255;
110:     }
111:   }
112:   ctx.putImageData(image, 0, 0);
113:   const texture = new THREE.CanvasTexture(canvas);
114:   texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
115:   texture.anisotropy = 8;
116:   return texture;
117: }
