119: function roughnessTexture(size, seed, base = 0.78, variation = 0.22, wet = 0) {
120:   const rand = mulberry32(seed);
121:   return canvasTexture(size, size, (ctx, w, h) => {
122:     const value = Math.round(base * 255);
123:     ctx.fillStyle = `rgb(${value},${value},${value})`;
124:     ctx.fillRect(0, 0, w, h);
125:     for (let i = 0; i < 2600; i++) {
126:       const v = Math.round(THREE.MathUtils.clamp(base + (rand() - 0.5) * variation, 0.02, 1) * 255);
127:       ctx.fillStyle = `rgba(${v},${v},${v},${0.12 + rand() * 0.3})`;
128:       const s = 1 + rand() * 5;
129:       ctx.fillRect(rand() * w, rand() * h, s, s);
130:     }
131:     if (wet > 0) {
132:       for (let i = 0; i < 22; i++) {
133:         const g = ctx.createRadialGradient(rand() * w, rand() * h, 1, rand() * w, rand() * h, 12 + rand() * 54);
134:         g.addColorStop(0, `rgba(20,20,20,${0.35 + rand() * 0.3})`);
135:         g.addColorStop(1, 'rgba(20,20,20,0)');
136:         ctx.fillStyle = g;
137:         ctx.fillRect(0, 0, w, h);
138:       }
139:     }
140:   }, { srgb: false });
141: }
