143: function drawRust(ctx, w, h, rand, amount = 40) {
144:   for (let i = 0; i < amount; i++) {
145:     const x = rand() * w;
146:     const y = rand() * h;
147:     const r = 1 + rand() * 12;
148:     const g = ctx.createRadialGradient(x, y, 0, x, y, r);
149:     g.addColorStop(0, `rgba(${90 + rand() * 45},${42 + rand() * 25},${20 + rand() * 15},${0.18 + rand() * 0.35})`);
150:     g.addColorStop(1, 'rgba(70,35,18,0)');
151:     ctx.fillStyle = g;
152:     ctx.fillRect(x - r, y - r, r * 2, r * 2);
153:   }
154: }
