442: // ---------------------------------------------------------------- buildings
443: export function windowTextures(seed) {
444:   const width = 512;
445:   const height = 1024;
446:   const rand = mulberry32(seed);
447:   const cols = 8;
448:   const rows = 20;
449:   const color = document.createElement('canvas');
450:   color.width = width;
451:   color.height = height;
452:   const c = color.getContext('2d');
453:   const emit = document.createElement('canvas');
454:   emit.width = width;
455:   emit.height = height;
456:   const e = emit.getContext('2d');
457:   const rough = document.createElement('canvas');
458:   rough.width = width;
459:   rough.height = height;
460:   const r = rough.getContext('2d');
461: 
462:   c.fillStyle = '#262e36';
463:   c.fillRect(0, 0, width, height);
464:   e.fillStyle = '#000';
465:   e.fillRect(0, 0, width, height);
466:   r.fillStyle = '#dcdcdc';
467:   r.fillRect(0, 0, width, height);
468: 
469:   // concrete grain and grime
470:   for (let i = 0; i < 5200; i++) {
471:     const g = 24 + rand() * 34;
472:     c.fillStyle = `rgba(${g},${g + 2},${g + 5},${0.12 + rand() * 0.28})`;
473:     c.fillRect(rand() * width, rand() * height, 1 + rand() * 3, 1 + rand() * 3);
474:   }
475:   for (let i = 0; i < 30; i++) {
476:     const g = c.createLinearGradient(0, 0, 0, height);
477:     g.addColorStop(0, `rgba(8,10,13,${0.05 + rand() * 0.12})`);
478:     g.addColorStop(1, 'rgba(8,10,13,0)');
479:     c.fillStyle = g;
480:     c.fillRect(rand() * width, 0, 1 + rand() * 10, height);
481:   }
482: 
483:   const padX = 22;
484:   const padY = 26;
485:   const cw = (width - padX * 2) / cols;
486:   const ch = (height - padY * 2) / rows;
487: 
488:   for (let row = 0; row < rows; row++) {
489:     // floor slab / spandrel band
490:     const bandY = padY + row * ch;
491:     c.fillStyle = row % 4 === 0 ? 'rgba(46,52,59,0.9)' : 'rgba(27,32,38,0.9)';
492:     c.fillRect(0, bandY, width, ch * 0.16);
493:     c.fillStyle = 'rgba(0,0,0,0.4)';
494:     c.fillRect(0, bandY + ch * 0.16, width, 2);
495: 
496:     for (let col = 0; col < cols; col++) {
497:       const ww = cw * 0.54;
498:       const hh = ch * 0.42;
499:       const x = padX + col * cw + (cw - ww) / 2;
500:       const y = bandY + ch * 0.34;
501:       const lit = rand() > 0.88;
502:       const warm = rand() > 0.38;
503:       const brightness = 0.18 + rand() * 0.32;
504: 
505:       // frame
506:       c.fillStyle = 'rgba(9,12,16,0.95)';
507:       c.fillRect(x - 3, y - 3, ww + 6, hh + 6);
508:       // glass
509:       const glass = c.createLinearGradient(x, y, x + ww, y + hh);
510:       if (lit) {
511:         glass.addColorStop(0, warm ? `rgba(255,206,150,${brightness})` : `rgba(178,222,255,${brightness})`);
512:         glass.addColorStop(1, warm ? `rgba(190,112,56,${brightness * 0.8})` : `rgba(84,136,180,${brightness * 0.8})`);
513:       } else {
514:         glass.addColorStop(0, 'rgba(18,25,34,0.95)');
515:         glass.addColorStop(0.45, 'rgba(28,39,52,0.95)');
516:         glass.addColorStop(1, 'rgba(11,16,22,0.95)');
517:       }
518:       c.fillStyle = glass;
519:       c.fillRect(x, y, ww, hh);
520:       // reflection streak on dark glass
521:       if (!lit) {
522:         c.fillStyle = `rgba(110,145,175,${0.06 + rand() * 0.09})`;
523:         c.beginPath();
524:         c.moveTo(x, y + hh * 0.1);
525:         c.lineTo(x + ww * 0.7, y);
526:         c.lineTo(x + ww, y);
527:         c.lineTo(x + ww * 0.3, y + hh);
528:         c.lineTo(x, y + hh);
529:         c.closePath();
530:         c.fill();
531:       }
532:       // mullions
533:       c.fillStyle = 'rgba(8,10,13,0.9)';
534:       c.fillRect(x + ww / 2 - 1, y, 2, hh);
535:       if (rand() > 0.55) c.fillRect(x, y + hh * 0.5 - 1, ww, 2);
536: 
537:       if (lit) {
538:         e.fillStyle = warm
539:           ? `rgba(255,${205 + rand() * 35},${160 + rand() * 35},${brightness})`
540:           : `rgba(${150 + rand() * 45},${205 + rand() * 35},255,${brightness * 0.9})`;
541:         e.fillRect(x, y, ww, hh);
542:         if (rand() > 0.72) {
543:           e.fillStyle = 'rgba(0,0,0,0.75)';
544:           e.fillRect(x + ww * (0.25 + rand() * 0.4), y, ww * 0.18, hh);
545:         }
546:         r.fillStyle = 'rgba(70,70,70,0.8)';
547:         r.fillRect(x, y, ww, hh);
548:       } else {
549:         r.fillStyle = 'rgba(58,58,58,0.9)';
550:         r.fillRect(x, y, ww, hh);
551:       }
552:     }
553:   }
554: 
555:   // vertical pilasters
556:   for (let col = 0; col <= cols; col++) {
557:     c.fillStyle = 'rgba(13,17,21,0.65)';
558:     c.fillRect(padX + col * cw - 3, 0, 3, height);
559:   }
560:   c.fillStyle = 'rgba(8,11,15,0.5)';
561:   for (let i = 0; i < 16; i++) c.fillRect(0, rand() * height, width, 1 + rand() * 3);
562: 
563:   const map = new THREE.CanvasTexture(color);
564:   map.colorSpace = THREE.SRGBColorSpace;
565:   map.anisotropy = 8;
566:   map.wrapS = map.wrapT = THREE.RepeatWrapping;
567:   const emissive = new THREE.CanvasTexture(emit);
568:   emissive.colorSpace = THREE.SRGBColorSpace;
569:   emissive.anisotropy = 8;
570:   emissive.wrapS = emissive.wrapT = THREE.RepeatWrapping;
571:   const roughness = new THREE.CanvasTexture(rough);
572:   roughness.anisotropy = 8;
573:   roughness.wrapS = roughness.wrapT = THREE.RepeatWrapping;
574:   return { map, emissive, roughness };
575: }
