673: function updateEffects(dt) {
674:   for (let i = effects.length - 1; i >= 0; i--) {
675:     const e = effects[i];
676:     e.life -= dt;
677:     const t = 1 - Math.max(0, e.life) / e.max;
678:     if (e.type === 'line') {
679:       e.obj.material.opacity = (1 - t) * 0.9;
680:     } else if (e.type === 'ring') {
681:       e.obj.scale.setScalar(1 + t * e.growth);
682:       e.obj.material.opacity = (1 - t) * 0.85;
683:     }
684:     if (e.life <= 0) {
685:       scene.remove(e.obj);
686:       e.obj.geometry.dispose();
687:       e.obj.material.dispose();
688:       effects.splice(i, 1);
689:     }
690:   }
691:   for (const slot of flashPool) {
692:     if (slot.life > 0) {
693:       slot.life -= dt;
694:       slot.light.intensity = Math.max(0, slot.life / slot.max) * slot.base;
695:     }
696:   }
697: }
