1031:     game.recoilYaw *= Math.exp(-8 * dt);
1032:   }
1033:   const speed = Math.hypot(player.vel.x, player.vel.z);
1034:   if (player.onGround) {
1035:     player.bobPhase += dt * speed * 1.65;
1036:     player.bob = Math.sin(player.bobPhase * 2) * 0.026 * Math.min(1, speed / 4);
1037:   }
1038:   const shake = game.shake * game.shake;
1039:   const sx = (Math.random() - 0.5) * shake * 0.22;
1040:   const sy = (Math.random() - 0.5) * shake * 0.22;
1041:   const sz = (Math.random() - 0.5) * shake * 0.12;
1042:   camera.position.set(player.pos.x + sx, player.pos.y + player.eye + player.bob + sy, player.pos.z + sz);
1043:   const strafe = (keys.has('KeyD') ? 1 : 0) - (keys.has('KeyA') ? 1 : 0);
1044:   const targetRoll = -strafe * 0.012;
1045:   player.roll = lerp(player.roll, targetRoll, 1 - Math.exp(-8 * dt));
1046:   camera.rotation.set(
1047:     player.pitch + game.recoil + sy * 0.15,
1048:     player.yaw + game.recoilYaw + sx * 0.15,
1049:     player.roll + (Math.random() - 0.5) * shake * 0.03
1050:   );
1051:   camera.updateMatrixWorld(true);
1052: }
