1061: function resolveCollisions() {
1062:   for (const c of world.colliders) {
1063:     if (c.type === 'circle') {
1064:       const dx = player.pos.x - c.x;
1065:       const dz = player.pos.z - c.z;
1066:       const d = Math.hypot(dx, dz);
1067:       const min = c.r + player.radius;
1068:       if (d < min && d > 0.0001) {
1069:         player.pos.x = c.x + (dx / d) * min;
1070:         player.pos.z = c.z + (dz / d) * min;
1071:       }
1072:     } else {
1073:       const cos = Math.cos(c.rot);
1074:       const sin = Math.sin(c.rot);
1075:       const dx = player.pos.x - c.x;
1076:       const dz = player.pos.z - c.z;
1077:       const lx = dx * cos + dz * sin;
1078:       const lz = -dx * sin + dz * cos;
1079:       const hx = c.halfW + player.radius;
1080:       const hz = c.halfD + player.radius;
1081:       if (Math.abs(lx) < hx && Math.abs(lz) < hz) {
1082:         const ox = hx - Math.abs(lx);
1083:         const oz = hz - Math.abs(lz);
1084:         let nlx = lx;
1085:         let nlz = lz;
1086:         if (ox < oz) nlx = Math.sign(lx || 1) * hx;
1087:         else nlz = Math.sign(lz || 1) * hz;
1088:         player.pos.x = c.x + nlx * cos - nlz * sin;
1089:         player.pos.z = c.z + nlx * sin + nlz * cos;
1090:       }
1091:     }
1092:   }
1093:   player.pos.x = clamp(player.pos.x, -29.2, 29.2);
1094:   player.pos.z = clamp(player.pos.z, -29.2, 29.2);
1095: }
