1097: function updatePlayer(dt) {
1098:   const forward = (keys.has('KeyW') ? 1 : 0) - (keys.has('KeyS') ? 1 : 0);
1099:   const strafe = (keys.has('KeyD') ? 1 : 0) - (keys.has('KeyA') ? 1 : 0);
1100:   let mx = strafe;
1101:   let mz = -forward;
1102:   if (isTouch) {
1103:     mx += touchMove.x;
1104:     mz += touchMove.y;
1105:     if (Math.hypot(mx, mz) > 1) {
1106:       const l = Math.hypot(mx, mz);
1107:       mx /= l; mz /= l;
1108:     }
1109:   }
1110:   const sprint = keys.has('ShiftLeft') || keys.has('ShiftRight');
1111:   const speed = sprint ? 7.4 : 5.1;
1112:   const cos = Math.cos(player.yaw);
1113:   const sin = Math.sin(player.yaw);
1114:   // forward is -Z, right is +X
1115:   const desiredX = (mx * cos + mz * sin) * speed;
1116:   const desiredZ = (-mx * sin + mz * cos) * speed;
1117:   const accel = player.onGround ? 12 : 3;
1118:   player.vel.x = lerp(player.vel.x, desiredX, 1 - Math.exp(-accel * dt));
1119:   player.vel.z = lerp(player.vel.z, desiredZ, 1 - Math.exp(-accel * dt));
1120:   player.vel.y -= 18 * dt;
1121:   player.pos.x += player.vel.x * dt;
1122:   player.pos.z += player.vel.z * dt;
1123:   player.pos.y += player.vel.y * dt;
1124:   if (player.pos.y <= 0) {
1125:     player.pos.y = 0;
1126:     player.vel.y = 0;
1127:     player.onGround = true;
1128:   }
1129:   resolveCollisions();
1130: 
1131:   // nudge props out of the way
1132:   for (const prop of props) {
1133:     if (prop.held) continue;
1134:     const dx = prop.group.position.x - player.pos.x;
1135:     const dz = prop.group.position.z - player.pos.z;
1136:     const d = Math.hypot(dx, dz);
1137:     const min = prop.radius + player.radius;
1138:     if (d < min && d > 0.001) {
1139:       const push = (min - d) * 0.7;
1140:       prop.group.position.x += (dx / d) * push;
1141:       prop.group.position.z += (dz / d) * push;
1142:       if (Math.hypot(player.vel.x, player.vel.z) > 1) {
1143:         prop.velocity.x += (dx / d) * 1.2;
1144:         prop.velocity.z += (dz / d) * 1.2;
1145:       }
1146:     }
1147:   }
1148: }
